

-- Handbook v1.14 remediation: distinct synthetic Nanjing lodging market; all identities and prices remain synthetic.
PRAGMA foreign_keys=OFF;
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'Hexitranslated business text' WHEN 1 THEN 'translated business textroom' WHEN 2 THEN 'South Stationtranslated business texthotel' WHEN 3 THEN 'translated business texthotel'
      WHEN 4 THEN 'translated business text' WHEN 5 THEN 'translated business texthotel' WHEN 6 THEN 'translated business text' WHEN 7 THEN 'translated business textshop'
      WHEN 8 THEN 'translated business text' WHEN 9 THEN 'translated business textroom' WHEN 10 THEN 'translated business texthotel' WHEN 11 THEN 'translated business textroom'
      WHEN 12 THEN 'translated business textcenter' WHEN 13 THEN 'Nanjing Southstationtranslated business textroom' WHEN 14 THEN 'Hexitranslated business textshop' WHEN 15 THEN 'translated business textmetrotranslated business text'
      ELSE 'translated business text' END AS lodging_name,
    CASE rowid % 19
      WHEN 0 THEN 'translated business text' WHEN 1 THEN 'translated business texttometrostation' WHEN 2 THEN 'translated business textnonelinetranslated business text' WHEN 3 THEN 'withouttranslated business text'
      WHEN 4 THEN 'translated business textordertranslated business text' WHEN 5 THEN 'beforetranslated business text' WHEN 6 THEN 'check-inday beforerefundable' WHEN 7 THEN 'translated business textafternonrefundable'
      WHEN 8 THEN 'translated business textattranslated business textpointbeforetranslated business textcheck-in' WHEN 9 THEN 'translated business text' WHEN 10 THEN 'translated business textitem' WHEN 11 THEN 'roomtranslated business text'
      WHEN 12 THEN 'translated business textticket' WHEN 13 THEN 'translated business textexam sitetranslated business text' WHEN 14 THEN 'translated business textorderpersontranslated business text' WHEN 15 THEN 'inventorytranslated business text'
      WHEN 16 THEN 'pricemaytranslated business textinventorychange' WHEN 17 THEN 'bookingbeforetranslated business textverifycanceltranslated business text' ELSE 'translated business textcandidatetranslated business text' END AS lodging_scope
  FROM hotels WHERE hotel_id LIKE 'HTL_NJ_DIST_%'
)
UPDATE hotels
SET name=CASE rowid % 5
      WHEN 0 THEN (SELECT lodging_name || '｜' || lodging_scope FROM facts WHERE facts.rid=hotels.rowid)
      WHEN 1 THEN (SELECT lodging_scope || 'of' || lodging_name FROM facts WHERE facts.rid=hotels.rowid)
      WHEN 2 THEN (SELECT lodging_name || '（' || lodging_scope || '）' FROM facts WHERE facts.rid=hotels.rowid)
      WHEN 3 THEN (SELECT 'Nanjingaccommodation：' || lodging_name || '；' || lodging_scope FROM facts WHERE facts.rid=hotels.rowid)
      ELSE (SELECT lodging_name || 'translated business textroom，' || lodging_scope FROM facts WHERE facts.rid=hotels.rowid)
    END,
    district=CASE rowid % 6 WHEN 0 THEN 'translated business textarea' WHEN 1 THEN 'translated business textarea' WHEN 2 THEN 'translated business textarea' WHEN 3 THEN 'translated business textarea' WHEN 4 THEN 'translated business textarea' ELSE 'translated business textarea' END,
    amenities_json=json_array('wifi',CASE rowid % 4 WHEN 0 THEN 'quiet_floor' WHEN 1 THEN 'luggage_storage' WHEN 2 THEN 'desk' ELSE 'late_checkin' END,CASE rowid % 3 WHEN 0 THEN 'breakfast' ELSE 'no_breakfast' END),
    address_json=json_object('city','Nanjing','district',CASE rowid % 6 WHEN 0 THEN 'translated business textarea' WHEN 1 THEN 'translated business textarea' WHEN 2 THEN 'translated business textarea' WHEN 3 THEN 'translated business textarea' WHEN 4 THEN 'translated business textarea' ELSE 'translated business textarea' END,'address_class','synthetic_business_location'),
    policies_json=json_object('refund',CASE rowid % 4 WHEN 0 THEN 'flex' WHEN 1 THEN 'prepaid' WHEN 2 THEN 'same_day_nonrefundable' ELSE 'partial_refund' END,'id_handling','front_desk_only','synthetic',1),
    description=CASE rowid % 7
      WHEN 0 THEN (SELECT lodging_name || 'ofsynthetictranslated business textsessionrecord；' || lodging_scope || '。' FROM facts WHERE facts.rid=hotels.rowid)
      WHEN 1 THEN (SELECT 'translated business textaccommodationcandidatefor' || lodging_name || '，translated business textitemis' || lodging_scope || '。' FROM facts WHERE facts.rid=hotels.rowid)
      WHEN 2 THEN (SELECT lodging_scope || '；translated business textandpricetranslated business textatbookingbeforetranslated business textquery。' FROM facts WHERE facts.rid=hotels.rowid)
      WHEN 3 THEN (SELECT 'translated business textcandidate：' || lodging_name || '。' || lodging_scope || '。' FROM facts WHERE facts.rid=hotels.rowid)
      WHEN 4 THEN (SELECT lodging_name || 'translated business textorderpersonroom；' || lodging_scope || '。' FROM facts WHERE facts.rid=hotels.rowid)
      WHEN 5 THEN (SELECT 'syntheticaccommodationtranslated business text' || lodging_name || '，translated business text' || lodging_scope || '。' FROM facts WHERE facts.rid=hotels.rowid)
      ELSE (SELECT 'accommodationtranslated business textfor' || lodging_name || '。filtertranslated business textbeforetranslated business text：' || lodging_scope || '。' FROM facts WHERE facts.rid=hotels.rowid)
    END,
    hotel_id=replace(hotel_id,'HTL_NJ_DIST_','HTL_NJ_MARKET_')
WHERE hotel_id LIKE 'HTL_NJ_DIST_%';
UPDATE rate_plans
SET hotel_id=replace(hotel_id,'HTL_NJ_DIST_','HTL_NJ_MARKET_'),
    cancellation_policy=CASE rowid % 4 WHEN 0 THEN 'check-inday before 18:00 beforerefundable' WHEN 1 THEN 'translated business textafternonrefundable' WHEN 2 THEN 'check-inday 12:00 beforetranslated business textroomtranslated business text' ELSE 'check-inbeforetranslated business textrefundable' END,
    refundable_until=CASE rowid % 4 WHEN 0 THEN '2026-08-19T18:00:00+08:00' WHEN 3 THEN '2026-08-17T18:00:00+08:00' ELSE NULL END
WHERE hotel_id LIKE 'HTL_NJ_DIST_%';
PRAGMA foreign_keys=ON;

UPDATE hotels
SET description='translated business textandnonelinetranslated business textoftranslated business textaccommodationrecord；check-inday before 18:00 beforerefundable，translated business textbookingbeforestilltranslated business textquerytranslated business textinventoryandtranslated business text。'
WHERE hotel_id='HTL_NJ_REFUNDABLE_01';
